/* Docket's chat: a calm transcript where only tone steps separate things. The prompt is a barely
   raised block with a small corner (no bubble color, a faint hairline), cards are a hairline on an
   almost invisible fill, secondary text is the tracker's cool gray, dim text the step under it, and
   links are the indigo a step toward the text so they read on either page.
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root: paint, so
   nothing in the transcript moves when this applies or reloads. Every color is made from the
   theme's own (--agent-text, --agent-accent, --agent-page-bg), so it reads over Docket and Docket
   Light and over any theme of your own. */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-text) 4%, transparent);
  --cv-user-bubble-edge: color-mix(in srgb, var(--agent-text) 8%, transparent);
  --cv-user-bubble-radius: 6px;
  --cv-card-fill: color-mix(in srgb, var(--agent-text) 3%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-text) 9%, transparent);
  --cv-text: var(--agent-text);
  --cv-text-muted: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --cv-text-dim: color-mix(in srgb, var(--agent-text) 66%, transparent);
  --cv-link: color-mix(in srgb, var(--agent-accent) 78%, var(--agent-text));
  --agent-link: color-mix(in srgb, var(--agent-accent) 78%, var(--agent-text));

  /* Pending cmux#46846 (--menu-*): the tracker's context menus and command menu. Inert until it lands.
     A panel one step off the page with a hairline and 8 px corners, a 4 px inset, 32 px rows, a
     neutral gray highlight (never colored) with a 6 px corner, shortcuts as quiet gray keys at the
     right, small medium-weight gray section labels, separators edge to edge, destructive rows in the
     theme's red (the default), and submenus that sit 4 px off their row with their first row level
     with it. */
  --menu-radius: 8px;
  --menu-padding: 4px;
  --menu-fill: color-mix(in srgb, var(--agent-text) 4%, var(--agent-page-bg));
  --menu-border: color-mix(in srgb, var(--agent-text) 10%, transparent);
  --menu-row-height: 32px;
  --menu-hover-fill: color-mix(in srgb, var(--agent-text) 8%, transparent);
  --menu-hover-radius: 6px;
  --menu-separator: color-mix(in srgb, var(--agent-text) 9%, transparent);
  --menu-separator-inset: 0px;
  --menu-label-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-label-weight: 500;
  --menu-label-size: var(--text-caption);
  --menu-shortcut-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-subtitle-color: color-mix(in srgb, var(--agent-text) 72%, transparent);
  --menu-disabled-opacity: 0.4;
  --menu-submenu-offset: 4px;
  --menu-submenu-align-offset: -4px;
}

